import { orders, products } from '@/lib/data'; // your data layer

const problem = (status: number, type: string, title: string) =>
  Response.json({ type, title, status }, { status, headers: { 'Content-Type': 'application/problem+json' } });

export async function POST(req: Request) {
  const key = req.headers.get('Idempotency-Key');
  if (!key) return problem(400, '/errors/missing-idempotency-key', 'Idempotency-Key header is required');

  const body = await req.json().catch(() => null);
  if (!body?.productId) return problem(422, '/errors/validation', 'productId is required');

  // Atomic: INSERT INTO idempotency_keys (key, ...) ON CONFLICT (key) DO NOTHING RETURNING key
  const claimed = await orders.claimKey(key);
  if (!claimed) {
    const prev = await orders.findByIdempotencyKey(key);
    if (!prev?.order) return problem(409, '/errors/in-progress', 'A request with this key is still running');
    return Response.json(prev.order, { status: 200 }); // replay: do not create or charge again
  }

  const product = await products.find(body.productId);
  if (!product || product.stock === 0) {
    await orders.releaseKey(key); // nothing happened, so a retry may run again
    return product ? problem(409, '/errors/out-of-stock', 'Out of stock') : problem(404, '/errors/not-found', 'Product not found');
  }

  try {
    const order = await orders.create({ productId: product.id, idempotencyKey: key });
    return Response.json(order, { status: 201, headers: { Location: `/api/orders/${order.id}` } });
  } catch (err) {
    await orders.releaseKey(key); // the order was not created, so let a retry run instead of 409 forever
    throw err;
  }
}

