import type { Request, Response, NextFunction } from 'express';

const ALLOWED = new Set([
  'https://app.example.com',
  'https://admin.example.com',
  ...(process.env.NODE_ENV !== 'production' ? ['http://localhost:5173'] : []),
]);

export function cors(req: Request, res: Response, next: NextFunction) {
  const origin = req.headers.origin;
  res.vary('Origin'); // response differs per origin: tell caches
  if (origin && ALLOWED.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin); // exact origin, never '*' with cookies
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    res.setHeader('Access-Control-Expose-Headers', 'X-Request-Id');
  }
  if (req.method === 'OPTIONS') {
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, Idempotency-Key');
    res.setHeader('Access-Control-Max-Age', '7200'); // Chromium's cap
    return res.status(204).end(); // before auth: preflights carry no credentials
  }
  next();
}

