import { createServer } from 'node:http';
import { bus, type Ev } from './bus'; // event log + pub/sub; subscribe() returns an unsubscribe fn

createServer(async (req, res) => {
  if (req.url !== '/events') return void res.writeHead(404).end();
  res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no' });
  res.write('retry: 5000\n\n'); // client reconnect delay in ms

  const send = (ev: Ev) => res.write(`id: ${ev.id}\nevent: ${ev.type}\ndata: ${JSON.stringify(ev.data)}\n\n`);

  // 1. Subscribe FIRST and buffer, so events published during the replay are not lost.
  const live: Ev[] = [];
  let replaying = true;
  const unsubscribe = bus.subscribe((ev) => (replaying ? live.push(ev) : send(ev)));
  const ping = setInterval(() => res.write(': ping\n\n'), 25_000); // under 60 s idle timeouts
  req.on('close', () => { clearInterval(ping); unsubscribe(); });

  // 2. Replay what the client missed, then flush the buffer without duplicates.
  const missed = await bus.since(req.headers['last-event-id'] as string | undefined);
  const sent = new Set(missed.map((ev) => ev.id));
  missed.forEach(send);
  live.filter((ev) => !sent.has(ev.id)).forEach(send);
  replaying = false;
}).listen(3000);

import { WebSocketServer, WebSocket } from 'ws';

const wss = new WebSocketServer({ port: 8080 });

export function broadcast(update: object) {
  const msg = JSON.stringify(update);
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) client.send(msg);
  }
}

