import { createServer } from 'node:http';
import { app } from './app';

let shuttingDown = false;

const server = createServer((req, res) => {
  if (req.url === '/livez') return void res.writeHead(200).end('ok');
  // Readiness fails during shutdown, so the LB stops sending new traffic.
  if (req.url === '/readyz') return void res.writeHead(shuttingDown ? 503 : 200).end();
  if (shuttingDown) res.setHeader('Connection', 'close'); // move keep-alive clients elsewhere
  app(req, res);
});

// Node 22/24/26 default is 5 s. Keep idle sockets open longer than the LB (ALB: 60 s).
server.keepAliveTimeout = 65_000;
server.listen(3000);

process.on('SIGTERM', () => {
  shuttingDown = true;
  // 1. Wait until the LB has seen /readyz fail (probe period x failure threshold).
  setTimeout(() => {
    // 2. Stop accepting, close idle sockets, let in-flight requests finish.
    server.close(() => process.exit(0));
    server.closeIdleConnections();
  }, 15_000);
  // 3. Hard stop before the platform sends SIGKILL (Kubernetes default grace: 30 s).
  setTimeout(() => process.exit(1), 28_000).unref();
});

